use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl DiagCtxt { pub fn disable_warnings (mut self) -> Self { self . inner . get_mut () . flags . can_emit_warnings = false ; self } pub fn with_flags (mut self , flags : DiagCtxtFlags) -> Self { self . inner . get_mut () . flags = flags ; self } pub fn with_ice_file (mut self , ice_file : PathBuf) -> Self { self . inner . get_mut () . ice_file = Some (ice_file) ; self } pub fn with_registry (mut self , registry : Registry) -> Self { self . inner . get_mut () . registry = registry ; self } pub fn new (emitter : Box < DynEmitter >) -> Self { Self { inner : Lock :: new (DiagCtxtInner :: new (emitter)) , } } pub fn make_silent (& self) { let mut inner = self . inner . borrow_mut () ; let translator = inner . emitter . translator () . clone () ; inner . emitter = Box :: new (emitter :: SilentEmitter { translator }) ; } pub fn set_emitter (& self , emitter : Box < dyn Emitter + DynSend >) { self . inner . borrow_mut () . emitter = emitter ; } # [doc = " Translate `message` eagerly with `args` to `SubdiagMessage::Eager`."] pub fn eagerly_translate < 'a > (& self , message : DiagMessage , args : impl Iterator < Item = DiagArg < 'a > > ,) -> SubdiagMessage { let inner = self . inner . borrow () ; inner . eagerly_translate (message , args) } # [doc = " Translate `message` eagerly with `args` to `String`."] pub fn eagerly_translate_to_string < 'a > (& self , message : DiagMessage , args : impl Iterator < Item = DiagArg < 'a > > ,) -> String { let inner = self . inner . borrow () ; inner . eagerly_translate_to_string (message , args) } pub fn can_emit_warnings (& self) -> bool { self . inner . borrow_mut () . flags . can_emit_warnings } # [doc = " Resets the diagnostic error count as well as the cached emitted diagnostics."] # [doc = ""] # [doc = " NOTE: *do not* call this function from rustc. It is only meant to be called from external"] # [doc = " tools that want to reuse a `Parser` cleaning the previously emitted diagnostics as well as"] # [doc = " the overall count of emitted error diagnostics."] pub fn reset_err_count (& self) { let mut inner = self . inner . borrow_mut () ; let DiagCtxtInner { flags : _ , registry : _ , err_guars , lint_err_guars , delayed_bugs , deduplicated_err_count , deduplicated_warn_count , emitter : _ , must_produce_diag , has_printed , suppressed_expected_diag , taught_diagnostics , emitted_diagnostic_codes , emitted_diagnostics , stashed_diagnostics , future_breakage_diagnostics , fulfilled_expectations , ice_file : _ , } = inner . deref_mut () ; * err_guars = Default :: default () ; * lint_err_guars = Default :: default () ; * delayed_bugs = Default :: default () ; * deduplicated_err_count = 0 ; * deduplicated_warn_count = 0 ; * must_produce_diag = None ; * has_printed = false ; * suppressed_expected_diag = false ; * taught_diagnostics = Default :: default () ; * emitted_diagnostic_codes = Default :: default () ; * emitted_diagnostics = Default :: default () ; * stashed_diagnostics = Default :: default () ; * future_breakage_diagnostics = Default :: default () ; * fulfilled_expectations = Default :: default () ; } pub fn handle < 'a > (& 'a self) -> DiagCtxtHandle < 'a > { DiagCtxtHandle { dcx : self , tainted_with_errors : None , } } # [doc = " Link this to a taintable context so that emitting errors will automatically set"] # [doc = " the `Option<ErrorGuaranteed>` instead of having to do that manually at every error"] # [doc = " emission site."] pub fn taintable_handle < 'a > (& 'a self , tainted_with_errors : & 'a Cell < Option < ErrorGuaranteed > > ,) -> DiagCtxtHandle < 'a > { DiagCtxtHandle { dcx : self , tainted_with_errors : Some (tainted_with_errors) , } } }